WITH valid AS (SELECT *, DATE_SUB(shipped_date, 74) shipped_date_minus_74d, UPPER(carrier) carrier_upper, COALESCE(carrier, 'N/A') resolved_carrier FROM shipments WHERE shipped_date > TO_DATE('2023-07-25') AND order_id IS NOT NULL AND shipped_date <= '2025-04-01') SELECT * FROM (SELECT status, carrier, cost FROM valid) src PIVOT (SUM(cost) FOR carrier IN ('DHL' AS dhl, 'UPS' AS ups))
